 19 │ function propTypeToString(pt: any): string {
 20 │   if (!pt || typeof pt !== 'object') return 'unknown'
 21 │   switch (pt.kind) {
 22 │     case 'string': {
 23 │       return 'string'
 24 │     }
 25 │     case 'number': {
 26 │       return 'number'
 27 │     }
 28 │     case 'boolean': {
 29 │       return 'boolean'
 30 │     }
 31 │     case 'null': {
 32 │       return 'null'
 33 │     }
 34 │     case 'undefined': {
 35 │       return 'undefined'
 36 │     }
 37 │     case 'any': {
 38 │       return 'any'
 39 │     }
 40 │     case 'never': {
 41 │       return 'never'
 42 │     }
 43 │     case 'unknown': {
 44 │       return 'unknown'
 45 │     }
 46 │     case 'void': {
 47 │       return 'void'
 48 │     }
 49 │     case 'reactNode': {
 50 │       return 'ReactNode'
 51 │     }
 52 │     case 'cssProperties': {
 53 │       return 'CSSProperties'
 54 │     }
 55 │     case 'elementType': {
 56 │       return 'ElementType'
 57 │     }
 58 │     case 'sxProps': {
 59 │       return 'SxProps'
 60 │     }
 61 │     case 'stringLiteral': {
 62 │       return JSON.stringify(pt.value)
 63 │     }
 64 │     case 'numberLiteral': {
 65 │       return String(pt.value)
 66 │     }
 67 │     case 'boolLiteral': {
 68 │       return String(pt.value)
 69 │     }
 70 │     case 'union': {
 71 │       return (pt.members as any[]).map((member) => propTypeToString(member)).join(' | ')
 72 │     }
 73 │     case 'intersection': {
 74 │       return (pt.members as any[]).map((member) => propTypeToString(member)).join(' & ')
 75 │     }
 76 │     case 'array': {
 77 │       return `${propTypeToString(pt.element)}[]`
 78 │     }
 79 │     case 'tuple': {
 80 │       return `[${(pt.elements as any[]).map((member) => propTypeToString(member)).join(', ')}]`
 81 │     }
 82 │     case 'object': {
 83 │       return '{ ... }'
 84 │     }
 85 │     case 'named': {
 86 │       return pt.args?.length ? `${pt.name}<${pt.args.map((member) => propTypeToString(member)).join(', ')}>` : pt.name
 87 │     }
 88 │     case 'eventHandler': {
 89 │       return `(${pt.paramName ?? 'e'}: ${pt.eventType}) => void`
 90 │     }
 91 │     case 'ref': {
 92 │       return pt.element ? `Ref<${pt.element}>` : 'Ref'
 93 │     }
 94 │     case 'htmlAttributes': {
 95 │       return `${pt.element}HTMLAttributes`
 96 │     }
 97 │     case 'literalUnion': {
 98 │       return pt.members.map((m: string) => JSON.stringify(m)).join(' | ')
 99 │     }
100 │     case 'opaque': {
101 │       return pt.raw
102 │     }
103 │     default: {
104 │       return JSON.stringify(pt)
105 │     }
106 │   }
107 │ }
