109 │ function normalize(output: any): NormalizedOutput {
110 │   const result: NormalizedOutput = {}
111 │   for (const [_key, comp] of Object.entries(output.components ?? {})) {
112 │     const c = comp as any
113 │     result[c.displayName] = {
114 │       displayName: c.displayName,
115 │       description: c.description ?? '',
116 │       props: Object.fromEntries(
117 │         Object.entries(c.props ?? {}).map(([propName, prop]: [string, any]) => [
118 │           propName,
119 │           {
120 │             name: propName,
121 │             required: prop.required ?? false,
122 │             type: propTypeToString(prop.type),
123 │             description: prop.description ?? '',
124 │             defaultValue: prop.defaultValue?.value,
125 │           },
126 │         ]),
127 │       ),
128 │     }
129 │   }
130 │   return result
131 │ }
132 │ 
133 │ // RDT always fully expands the real HTMLAttributes/AriaAttributes/<Element>HTMLAttributes
134 │ // interface chain (~250-300 attrs) — it has a real type checker to walk that chain. Our
135 │ // default (`curated`) intentionally surfaces a hand-picked ~15-20 common attrs instead (see
136 │ // ARCHITECTURE.md). Comparing curated-mode output against RDT's always-full output would
137 │ // manufacture a huge "missing props" number that's actually just a default-mode mismatch, not
138 │ // a real coverage gap — pass `--html-attributes full` here so this baseline is apples-to-apples
139 │ // with what RDT itself always does.
140 │ const HTML_ATTRIBUTES_MODE = process.env.HTML_ATTRIBUTES_MODE ?? 'full'
141 │ 
142 │ const libraries = discoverLibraries()
143 │ const results: ToolResult[] = []
144 │ 
145 │ // One CLI invocation across every fixture library at once (`--src` takes a
146 │ // comma-delimited list — see crates/cli/src/main.rs's `value_delimiter = ','`)
147 │ // instead of one process per library. Spawning 21 separate processes measured
148 │ // ~885ms dominated by process-startup overhead (~40ms/spawn), even though the
149 │ // tool's own internal "durationMs" stat for the combined single-invocation
150 │ // run is ~40-50ms — a single invocation is both the fair cold-extraction
151 │ // number AND how anyone would actually run this CLI in practice; nobody
152 │ // invokes it once per library directory in a real build.
153 │ {
154 │   const srcDirs = libraries.map((lib) => resolve(FIXTURES_ROOT, lib)).join(',')
155 │   const start = performance.now()
156 │   try {
157 │     const raw = execSync(
158 │       `${CLI} extract --src ${srcDirs} --format canonical --html-attributes ${HTML_ATTRIBUTES_MODE}`,
159 │       {
160 │         encoding: 'utf8',
161 │         stdio: ['pipe', 'pipe', 'pipe'],
162 │         maxBuffer: 100 * 1024 * 1024,
163 │       },
164 │     )
165 │     // CLI prints a spinner line then JSON — find the JSON start
166 │     const jsonStart = raw.indexOf('{')
167 │     const json = jsonStart === -1 ? raw : raw.slice(jsonStart)
168 │     const parsed = JSON.parse(json)
169 │     const durationMs = performance.now() - start
170 │ 
171 │     for (const [_key, comp] of Object.entries(parsed.components ?? {})) {
172 │       const c = comp as any
173 │       const inheritedElements = (c.inheritance ?? []).map((l: any) => l.htmlElement).filter(Boolean)
174 │       const notableInheritedNames = Object.keys(c.notableInherited ?? {})
175 │       // Derive the owning library dir from the absolute filePath (the fixtures/<lib>/
176 │       // segment) now that one invocation covers every library at once.
177 │       const fixturesIdx = c.filePath.indexOf('/fixtures/')
178 │       const relPath = fixturesIdx === -1 ? c.filePath : c.filePath.slice(fixturesIdx + '/fixtures/'.length)
179 │       const [lib] = relPath.split('/')
180 │       const basename =
181 │         c.filePath
182 │           .split('/')
183 │           .pop()
184 │           ?.replace(/\.tsx?$/, '')
185 │           .replace(/\.d$/, '') ?? c.displayName
186 │       results.push({
187 │         tool: 'oxc-react-docgen',
188 │         fixture: `${lib}/${basename}/${c.displayName}`,
189 │         durationMs,
190 │         output: normalize({ components: { [c.displayName]: c } }),
191 │         inheritedElements,
192 │         notableInheritedNames,
193 │       })
194 │     }
195 │   } catch (error: any) {
196 │     results.push({
197 │       tool: 'oxc-react-docgen',
198 │       fixture: 'all-fixtures',
199 │       durationMs: performance.now() - start,
200 │       output: {},
201 │       error: error.stderr ?? error.message,
202 │     })
203 │   }
204 │ }
205 │ 
206 │ console.log(JSON.stringify(results, null, 2))

