cd /Users/gabe/Projects/oxc-react-codegen/apps/validate && node --input-type=module - <<'EOF'
import { readFileSync } from 'node:fs'
const load = n => new Map(JSON.parse(readFileSync(`./baselines/${n}.json`,'utf8')).map(r=>[r.fixture,r]))
const ours = load('oxc-react-docgen'), rdt = load('react-docgen-typescript')
let n=0
const byKey={}
for (const [key,or] of ours){
 const tr=rdt.get(key); if(!tr) continue
 const [oc]=Object.values(or.output), [tc]=Object.values(tr.output)
 for(const p of Object.keys(oc.props)){ const cp=tc.props[p]; if(!cp) continue; const op=oc.props[p]
  if(op.type===cp.type && (op.defaultValue??null)!==(cp.defaultValue??null)){ n++; byKey[key]=(byKey[key]||0)+1; if(n<=45) console.log(key,p,'ours=',JSON.stringify(op.defaultValue),typeof op.defaultValue,' rdt=',JSON.stringify(cp.defaultValue),typeof cp.defaultValue)}
 }
}
console.log(n,byKey)
// Also: in type-mismatch props, do defaults/required also differ? and description agreement stat (not measured by tool)
let descDiff=0, descBoth=0, oursEmpty=0, rdtEmpty=0
let reqDiff=0, typeAndDefDiff=0
for (const [key,or] of ours){
 const tr=rdt.get(key); if(!tr) continue
 const [oc]=Object.values(or.output), [tc]=Object.values(tr.output)
 for(const p of Object.keys(oc.props)){ const cp=tc.props[p]; if(!cp) continue; const op=oc.props[p]
  descBoth++; if(op.description!==cp.description) descDiff++
  if(!op.description) oursEmpty++; if(!cp.description) rdtEmpty++
  if(op.required!==cp.required) reqDiff++
  if(op.type!==cp.type && (op.defaultValue??null)!==(cp.defaultValue??null)) typeAndDefDiff++
 }
}
console.log({descBoth,descDiff,oursEmpty,rdtEmpty,reqDiff,typeAndDefDiff})
EOF

