import { readFileSync } from 'node:fs'
const load = n => new Map(JSON.parse(readFileSync(`./baselines/${n}.json`,'utf8')).map(r=>[r.fixture,r]))
const ours = load('oxc-react-docgen-none'), rdt = load('react-docgen')
const norm=x=>x.replaceAll(/\s+/g,' ').replaceAll('"',"'").trim()
const strip=x=>x.split('|').map(m=>m.trim()).filter(m=>m!=='undefined').join(' | ')
const lit=x=>/^['"]/.test(x.trim())||x.includes('|')
const W=new Set(['string','number','boolean','unknown','any'])
function cls(o,t){
 if(norm(o)===norm(t)) return 'cosmetic-formatting'
 if(strip(o)===strip(t)&&o!==t) return 'optional-undefined-representation'
 const om=o.split('|').map(m=>m.trim()), tm=t.split('|').map(m=>m.trim())
 if(om.length>1&&om.length===tm.length&&new Set(om).size===om.length&&[...om].toSorted().join('|')===[...tm].toSorted().join('|')&&o!==t) return 'union-member-order'
 if((W.has(t.trim())&&lit(o))||(W.has(o.trim())&&lit(t))) return 'literal-narrowed-vs-widened'
 return 'structural-type-difference'
}
let cc=0,empty=0; const s={union:0,matched:0,mism:0,miss:0,missHtml:0,extra:0,type:0,req:0,def:0}; const b={}
for (const [key,or] of ours){
 const tr=rdt.get(key); if(!tr||or.error||tr.error) continue
 const [oc]=Object.values(or.output), [tc]=Object.values(tr.output); if(!oc||!tc) continue
 cc++; if(!Object.keys(tc.props).length) empty++
 const nb=new Set(or.notableInheritedNames)
 for(const p of new Set([...Object.keys(oc.props),...Object.keys(tc.props)])){
  const op=oc.props[p], cp=tc.props[p]; s.union++
  if(op&&!cp){s.extra++;continue}
  if(!op&&cp){ nb.has(p)?s.missHtml++:s.miss++; continue}
  if(op.required!==cp.required){s.mism++;s.req++;continue}
  if(op.type!==cp.type){const k=cls(op.type,cp.type); b[k]=(b[k]||0)+1; if(k==='cosmetic-formatting') s.matched++; else {s.mism++;s.type++}}
  else if((op.defaultValue??null)===(cp.defaultValue??null)) s.matched++; else {s.mism++;s.def++}
 }
}
console.log({cc,empty,...s,agreement:(s.matched/(s.union-s.missHtml)).toFixed(4)},b)
EOF

