import { readFileSync } from 'node:fs'
const load = n => new Map(JSON.parse(readFileSync(`./baselines/${n}.json`,'utf8')).map(r=>[r.fixture,r]))
const ours = load('oxc-react-docgen'), rdt = load('react-docgen-typescript')
const c={}
let all=0
for (const [key,or] of ours){
 const tr=rdt.get(key); if(!tr) continue
 const [oc]=Object.values(or.output), [tc]=Object.values(tr.output)
 for(const p of Object.keys(oc.props)){ const cp=tc.props[p]; if(!cp) continue; const op=oc.props[p]
  const od=op.defaultValue, td=cp.defaultValue
  if((od??null)===(td??null)) continue
  all++
  let k
  if(od===undefined) k='ours has no default, RDT has one'
  else if(td===undefined) k='RDT has no default, ours has one'
  else if(typeof td!=='string' && String(td)===od) k='same value, RDT typed '+typeof td+' vs ours string'
  else if(typeof td==='string' && (od===`"${td}"`||od===`'${td}'`)) k='same string, ours keeps source quotes'
  else k='different value'
  c[k]=(c[k]||0)+1
 }
}
console.log(all,c)
// count of props (both sides) where either has default and equal
let eq=0; for (const [key,or] of ours){const tr=rdt.get(key); if(!tr) continue; const [oc]=Object.values(or.output), [tc]=Object.values(tr.output); for(const p of Object.keys(oc.props)){const cp=tc.props[p]; if(cp && cp.defaultValue!==undefined && oc.props[p].defaultValue===cp.defaultValue) eq++}}
console.log('props with equal non-null default (strict ===):',eq)
EOF

